function rampartSimulate(createStrategy, seed, maxTicks, rec) {
  "use strict";
  var TN = ["bolt", "cannon", "frost", "lance", "flak"];
  var TCOST = [50, 90, 70, 120, 80], TDMG = [26, 60, 10, 180, 40], TPER = [8, 24, 12, 36, 10];
  var TRNG = [300, 260, 240, 360, 320], TSPL = [0, 90, 0, 0, 70], TSLOW = [0, 0, 30, 0, 0];
  var TPIERCE = [0, 0, 0, 1, 0], TGND = [1, 1, 1, 1, 0], TAIR = [1, 0, 1, 0, 1];
  var EN = ["grunt", "runner", "wisp", "brute", "splitter", "mender", "splitling"];
  var EHP = [60, 40, 50, 150, 90, 70, 0], ESPD = [10, 20, 12, 6, 8, 8, 12], EBTY = [4, 4, 6, 9, 6, 7, 1];
  var ELEAK = [1, 1, 2, 3, 2, 2, 1], EAIR = [0, 0, 1, 0, 0, 0, 0], EFIRST = [1, 2, 3, 4, 6, 8], EWT = [10, 4, 3, 3, 2, 1];
  var SLOTS = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  function mkRoute(tp) {
    var pts = [], cum = [0], i;
    for (i = 0; i < tp.length; i++) pts.push([tp[i][0] * 100 + 50, tp[i][1] * 100 + 50]);
    for (i = 1; i < pts.length; i++) cum.push(cum[i - 1] + Math.abs(pts[i][0] - pts[i - 1][0]) + Math.abs(pts[i][1] - pts[i - 1][1]));
    return { pts: pts, cum: cum, len: cum[cum.length - 1] };
  }
  var ROUTES = [
    mkRoute([[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]]),
    mkRoute([[0,6],[21,6],[21,11],[23,11]])
  ];
  function posOf(e) {
    var r = ROUTES[e.air], p = e.progress, i;
    if (p >= r.len) p = r.len;
    for (i = 1; i < r.pts.length - 1 && r.cum[i] < p; i++) {}
    if (r.cum[i] < p) i = r.pts.length - 1;
    var a = r.pts[i - 1], b = r.pts[i], d = p - r.cum[i - 1];
    var sx = b[0] > a[0] ? 1 : (b[0] < a[0] ? -1 : 0), sy = b[1] > a[1] ? 1 : (b[1] < a[1] ? -1 : 0);
    e.x = a[0] + sx * d; e.y = a[1] + sy * d;
  }
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
