  var mult = [0, 1000];
  function mOf(w) { while (mult.length <= w) mult.push(Math.floor(mult[mult.length - 1] * 108 / 100)); return mult[w]; }
  function genWave(w) {
    var n = 4 + Math.floor(3 * w / 5), out = [], tot = 0, k, i;
    for (k = 0; k < 6; k++) if (EFIRST[k] <= w) tot += EWT[k];
    for (i = 0; i < n; i++) {
      var r = rng() % tot;
      for (k = 0; k < 6; k++) { if (EFIRST[k] > w) continue; if (r < EWT[k]) break; r -= EWT[k]; }
      out.push(k);
    }
    return out;
  }
  var waves = [null, genWave(1)];
  var gold = 250, baseHp = 10, wave = 0, nextId = 1, log = [], enemies = [], queue = [];
  var turrets = []; for (var s0 = 0; s0 < 16; s0++) turrets.push(null);
  var strat = createStrategy();
  var hasTarget = strat && typeof strat.target === "function";
  var fallTick = -1, tick = 0;
  var fr = null;

  function view(e) {
    return { id: e.id, type: EN[e.type], hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.air, armor: e.armor,
      speed: ESPD[e.type], slowed: e.slow > 0 ? 1 : 0, remaining: ROUTES[e.air].len - e.progress };
  }
  function makeEnemy(type, w, mh, prog) {
    var e = { id: nextId++, type: type, wave: w, maxHp: mh, hp: mh, air: EAIR[type],
