      if (!a || typeof a !== "object") continue;
      var sl = a.slot;
      if (typeof sl !== "number" || sl !== Math.floor(sl) || sl < 0 || sl > 15) continue;
      var t = turrets[sl];
      if (a.op === "build") {
        var ti = TN.indexOf(a.type);
        if (t || ti < 0 || typeof a.type !== "string" || gold < TCOST[ti]) continue;
        gold -= TCOST[ti];
        turrets[sl] = { type: ti, tier: 1, spent: TCOST[ti], cd: 0, dmg: TDMG[ti], rng: TRNG[ti] };
