        t.dmg = Math.floor(t.dmg * 16 / 10); t.rng += 30;
        log.push([tick, "U", sl, t.tier]);
        if (fr) fr.ev.push([1, sl, t.type, t.tier]);
      } else if (a.op === "sell") {
        if (!t) continue;
        gold += Math.floor(t.spent * 70 / 100);
