    }
    fr.enemies = es; fr.gold = gold; fr.baseHp = baseHp; fr.wave = wave;
    var ts = [];
    for (var j = 0; j < 16; j++) ts.push(turrets[j] ? [turrets[j].type, turrets[j].tier] : null);
    fr.turrets = ts;
    rec.frames.push(fr);
  }
  if (rec) { rec.frames = []; rec.waves = waves; }

  mainLoop:
  for (tick = 0; tick < maxTicks; tick++) {
    if (rec) fr = { tick: tick, ev: [], shots: [], kills: [], heals: [], leaks: [], spawns: [], nextWave: null };
    // 1. wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      wave = (tick - 20) / 40 + 1;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * wave;
      waves[wave + 1] = genWave(wave + 1);
      var st = { tick: tick, wave: wave, gold: gold, baseHp: baseHp, slots: [], enemies: [], nextWave: [] };
      for (var si = 0; si < 16; si++) {
        var tt = turrets[si];
        st.slots.push({ slot: si, x: SLOTS[si][0], y: SLOTS[si][1], turret: tt ? { type: TN[tt.type], tier: tt.tier, spent: tt.spent } : null });
      }
      for (var ei = 0; ei < enemies.length; ei++) st.enemies.push(view(enemies[ei]));
      for (var ni = 0; ni < waves[wave + 1].length; ni++) st.nextWave.push(EN[waves[wave + 1][ni]]);
      applyActions(strat.plan(st));
      var comp = waves[wave];
      for (var qi = 0; qi < comp.length; qi++) queue.push({ t: tick + 4 * qi, w: wave, i: qi, type: comp[qi] });
      queue.sort(function (p, q) { return p.t - q.t || p.w - q.w || p.i - q.i; });
      if (fr) fr.nextWave = waves[wave + 1].slice();
    }
    // 2. spawn
    while (queue.length && queue[0].t <= tick) {
      var qq = queue.shift();
      var ne = makeEnemy(qq.type, qq.w, Math.floor(EHP[qq.type] * mOf(qq.w) / 1000), 0);
      enemies.push(ne);
      if (fr) fr.spawns.push(ne.id);
    }
    // 3. move
    for (var mi = 0; mi < enemies.length; mi++) {
      var me = enemies[mi];
      var sp = me.slow > 0 ? Math.floor(ESPD[me.type] * 60 / 100) : ESPD[me.type];
      me.progress += sp;
      if (me.progress >= ROUTES[me.air].len) {
        me.progress = ROUTES[me.air].len;
        baseHp -= ELEAK[me.type];
        log.push([tick, "L", me.id, baseHp]);
        if (fr) fr.leaks.push([me.id, me.type, baseHp]);
        enemies.splice(mi, 1); mi--;
        if (baseHp <= 0) {
          log.push([tick, "F", wave, 0]);
          fallTick = tick;
          snapshot();
          break mainLoop;
        }
      } else posOf(me);
    }
    // 4. age & heal
    for (var ai = 0; ai < enemies.length; ai++) {
      var ae = enemies[ai];
      ae.age++;
      if (ae.type === 5 && ae.age % 20 === 0) {
        if (fr) fr.heals.push([ae.x, ae.y]);
        for (var hi = 0; hi < enemies.length; hi++) {
          var he = enemies[hi], hx = he.x - ae.x, hy = he.y - ae.y;
          if (hx * hx + hy * hy <= 22500) {
            he.hp = Math.min(he.maxHp, he.hp + Math.floor(he.maxHp * 8 / 100));
          }
        }
      }
    }
    // 5. turrets
    for (var ts = 0; ts < 16; ts++) {
      var T = turrets[ts];
      if (!T) continue;
      if (T.cd > 0) { T.cd--; if (T.cd > 0) continue; }
      var tx = SLOTS[ts][0] * 100 + 50, ty = SLOTS[ts][1] * 100 + 50, r2 = T.rng * T.rng, ty0 = T.type;
      var cands = [];
      for (var ci = 0; ci < enemies.length; ci++) {
        var ce = enemies[ci];
        if (ce.air ? !TAIR[ty0] : !TGND[ty0]) continue;
        var dx = ce.x - tx, dy = ce.y - ty;
        if (dx * dx + dy * dy <= r2) cands.push(ce);
      }
      if (!cands.length) continue;
      var tgt = null;
      if (hasTarget) {
        var cv = [];
        for (var vi = 0; vi < cands.length; vi++) cv.push(view(cands[vi]));
        var rid = strat.target({ slot: ts, type: TN[ty0], tier: T.tier, x: tx, y: ty, range: T.rng }, cv);
        for (var vj = 0; vj < cands.length; vj++) if (cands[vj].id === rid) { tgt = cands[vj]; break; }
      }
      if (!tgt) {
        tgt = cands[0];
        for (var dj = 1; dj < cands.length; dj++) if (cands[dj].progress > tgt.progress && (ROUTES[cands[dj].air].len - cands[dj].progress) < (ROUTES[tgt.air].len - tgt.progress)) tgt = cands[dj];
      }
      var hits = [];
      if (TSPL[ty0] > 0) {
        var s2 = TSPL[ty0] * TSPL[ty0];
        for (var hj = 0; hj < enemies.length; hj++) {
          var he2 = enemies[hj];
          if (he2.air ? !TAIR[ty0] : !TGND[ty0]) continue;
          var ex = he2.x - tgt.x, ey = he2.y - tgt.y;
          if (ex * ex + ey * ey <= s2) hits.push(he2);
        }
      } else hits.push(tgt);
      for (var hk = 0; hk < hits.length; hk++) {
        var H = hits[hk];
        H.hp -= TPIERCE[ty0] ? T.dmg : Math.max(1, T.dmg - H.armor);
        if (TSLOW[ty0]) H.slow = TSLOW[ty0];
      }
      T.cd = TPER[ty0];
      if (fr) fr.shots.push([ts, ty0, tgt.id, tgt.x, tgt.y, tgt.air]);
      var dead = false;
      for (var dk = 0; dk < enemies.length; dk++) if (enemies[dk].hp <= 0) { dead = true; break; }
      if (dead) {
        var alive = [], born = [];
        for (var dl = 0; dl < enemies.length; dl++) {
          var D = enemies[dl];
          if (D.hp > 0) { alive.push(D); continue; }
          gold += EBTY[D.type];
          log.push([tick, "K", D.id, ts]);
          if (fr) fr.kills.push([D.id, D.type, D.x, D.y, D.air, ts]);
          if (D.type === 4) {
            var smh = Math.max(1, Math.floor(D.maxHp / 4));
            for (var k3 = 0; k3 < 3; k3++) {
              var sl3 = makeEnemy(6, D.wave, smh, D.progress);
              born.push(sl3);
              if (fr) fr.spawns.push(sl3.id);
            }
          }
        }
        enemies = alive.concat(born);
      }
    }
    // 6. slow timers
    for (var wi = 0; wi < enemies.length; wi++) if (enemies[wi].slow > 0) enemies[wi].slow--;
    snapshot();
  }
  var endTick = fallTick >= 0 ? fallTick : maxTicks;
  var score = Math.round((endTick - 20) / 40 * 100) / 100;
  var str = JSON.stringify(log), h = 0x811c9dc5;
  for (var hc = 0; hc < str.length; hc++) { h ^= str.charCodeAt(hc); h = Math.imul(h, 0x01000193); }
  var hs = (h >>> 0).toString(16); while (hs.length < 8) hs = "0" + hs;
  return { score: score, fallTick: fallTick, log: log, hash: hs };
}

