function createStrategy() {
  "use strict";
  var TYPES = ["bolt", "cannon", "frost", "lance", "flak"];
  var COST = [50, 90, 70, 120, 80];
  var SPL = [0, 90, 0, 0, 70];
  var SLOT_TYPES = __TYPES__;
  var SEQ = __SEQ__;
  var POLICY = __TP__;
  // own copy of the route geometry, so positions come from `remaining` only
  function mkRoute(tp) {
    var p = [], c = [0], i;
    for (i = 0; i < tp.length; i++) p.push([tp[i][0] * 100 + 50, tp[i][1] * 100 + 50]);
    for (i = 1; i < p.length; i++) c.push(c[i - 1] + Math.abs(p[i][0] - p[i - 1][0]) + Math.abs(p[i][1] - p[i - 1][1]));
    return { p: p, c: c, L: c[c.length - 1] };
  }
  var RT = [mkRoute([[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]]), mkRoute([[0,6],[21,6],[21,11],[23,11]])];
  function sgn(v) { return v > 0 ? 1 : (v < 0 ? -1 : 0); }
  function pos(e) {
    var r = RT[e.air ? 1 : 0], pr = r.L - e.remaining, i = 1;
    if (pr < 0) pr = 0;
    while (i < r.p.length - 1 && r.c[i] < pr) i++;
    var a = r.p[i - 1], b = r.p[i], d = pr - r.c[i - 1];
    return [a[0] + sgn(b[0] - a[0]) * d, a[1] + sgn(b[1] - a[1]) * d];
  }
  function first(c) { var b = 0; for (var i = 1; i < c.length; i++) if (c[i].remaining < c[b].remaining) b = i; return c[b].id; }
  function pick(k, c, ti) {
    var b = 0, i;
    if (k === 1) { for (i = 1; i < c.length; i++) if (c[i].hp > c[b].hp || (c[i].hp === c[b].hp && c[i].remaining < c[b].remaining)) b = i; return c[b].id; }
    if (k === 2) { b = -1; for (i = 0; i < c.length; i++) if (!c[i].slowed && (b < 0 || c[i].remaining < c[b].remaining)) b = i; return b < 0 ? first(c) : c[b].id; }
