      var r = SPL[ti] || 90, r2 = r * r, ps = [], bs = 0, bn = -1, j;
      for (i = 0; i < c.length; i++) ps.push(pos(c[i]));
      for (i = 0; i < c.length; i++) {
        var n = 0;
        for (j = 0; j < c.length; j++) { var dx = ps[i][0] - ps[j][0], dy = ps[i][1] - ps[j][1]; if (dx * dx + dy * dy <= r2) n++; }
