        tier[sl]++; pos0++;
      }
      return acts;
    },
    target: function (turret, cands) {
      var ti = TYPES.indexOf(turret.type);
      if (ti < 0 || !cands || !cands.length) return undefined;
      return pick(POLICY[ti], cands, ti);
    }
  };
