// genome-driven strategy for search
var TYPES = ["bolt", "cannon", "frost", "lance", "flak"];
var COST = [50, 90, 70, 120, 80];
function makeGenomeStrategy(g) {
  return function () {
    var pos = 0;
    var tierOf = []; for (var i = 0; i < 16; i++) tierOf.push(0);
    var rs = g.res || [0, 0, 0];
    return {
      plan: function (s) {
        var gold = s.gold, acts = [];
        var reserve = s.wave < rs[2] ? Math.min(rs[0], rs[1] * s.wave) : 0;
        for (var i = 0; i < 16; i++) { var t = s.slots[i].turret; tierOf[i] = t ? t.tier : 0; }
        while (pos < g.seq.length && acts.length < 32) {
          var sl = g.seq[pos], ty = g.types[sl], tier = tierOf[sl];
          if (tier >= 3) { pos++; continue; }
          var c = tier === 0 ? COST[ty] : COST[ty] * tier;
          if (gold - c < (pos < (g.free || 0) ? 0 : reserve)) break;
          gold -= c;
          acts.push(tier === 0 ? { op: "build", slot: sl, type: TYPES[ty] } : { op: "upgrade", slot: sl });
          tierOf[sl]++; pos++;
        }
        return acts;
      },
      target: g.tgt ? function (t, c) { return g.tgt(t, c); } : undefined
    };
  };
}
function evalGenome(g, seeds, maxT) {
  var sum = 0, res = [];
  for (var i = 0; i < seeds.length; i++) { var r = rampartSimulate(makeGenomeStrategy(g), seeds[i], maxT || 12020); sum += r.score; res.push(r.score); }
  return { mean: sum / seeds.length, res: res };
}

